SELECT id, member_name, phone, level, points, last_order_date,
       total_orders, total_spent, status, tag, tenant_id
FROM retention_member
WHERE 1 = 0
  AND tenant_id = #{tenantId}
LIMIT #{limit}

SELECT id, member_name, phone, level, points, last_order_date,
       total_orders, total_spent, status, tag, tenant_id
FROM retention_member
WHERE 1 = 0
  AND tenant_id = #{tenantId}
  AND level = #{level}

SELECT COUNT(1)
FROM retention_member
WHERE 1 = 0
  AND tenant_id = #{tenantId}
  AND level = #{level}
